import{_ as o,o as l,c as i,a5 as n}from"./chunks/framework.Cooo9kuv.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"816-批量将图片分别转为pdf，文件夹下所有图片转为一个pdf","日期":"2026-04-13T00:00:00.000Z","修改日期":"2026-04-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["PDF批处理","图片批处理"],"标签":["PDF转换工具","softbangong","图片处理工具","图片转pdf","批量处理图片","批量转换PDF","文档扫描转换","照片转PDF"]},"headers":[{"level":3,"title":"批量将图片分别转为pdf，文件夹下所有图片转为一个pdf","slug":"批量将图片分别转为pdf-文件夹下所有图片转为一个pdf","link":"#批量将图片分别转为pdf-文件夹下所有图片转为一个pdf","children":[]},{"level":3,"title":"功能特点","slug":"功能特点","link":"#功能特点","children":[]},{"level":3,"title":"程序说明","slug":"程序说明","link":"#程序说明","children":[]},{"level":3,"title":"基本操作指南","slug":"基本操作指南","link":"#基本操作指南","children":[]},{"level":3,"title":"实际使用场景示例","slug":"实际使用场景示例","link":"#实际使用场景示例","children":[]},{"level":3,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":3,"title":"📑 程序使用环境及相关说明","slug":"📑-程序使用环境及相关说明","link":"#📑-程序使用环境及相关说明","children":[]},{"level":3,"title":"常见问题解答","slug":"常见问题解答","link":"#常见问题解答","children":[]},{"level":3,"title":"📑 程序使用说明","slug":"📑-程序使用说明","link":"#📑-程序使用说明","children":[]}],"relativePath":"md/PDF批处理/816-批量将图片分别转为pdf，文件夹下所有图片转为一个pdf.md","filePath":"md/PDF批处理/816-批量将图片分别转为pdf，文件夹下所有图片转为一个pdf.md"}'),r={name:"md/PDF批处理/816-批量将图片分别转为pdf，文件夹下所有图片转为一个pdf.md"};function s(e,t,a,g,u,p){return l(),i("div",null,[...t[0]||(t[0]=[n('<h3 id="批量将图片分别转为pdf-文件夹下所有图片转为一个pdf" tabindex="-1">批量将图片分别转为pdf，文件夹下所有图片转为一个pdf <a class="header-anchor" href="#批量将图片分别转为pdf-文件夹下所有图片转为一个pdf" aria-label="Permalink to &quot;批量将图片分别转为pdf，文件夹下所有图片转为一个pdf&quot;">​</a></h3><p>无论您是需要将多张照片合并成一个PDF文档，还是希望每张图片单独生成PDF文件，本工具都能满足您的需求。通过简洁友好的界面，您可以轻松完成图片添加、顺序调整、批量转换等操作，大大提高工作效率。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251021141051176102705120029.png" alt=""></p><h3 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h3><ul><li><strong>批量处理</strong>：支持一次性添加多张图片或整个文件夹的图片进行批量转换</li><li><strong>灵活转换</strong>：可选择将所有图片合并为一个PDF或每张图片单独生成PDF</li><li><strong>拖放操作</strong>：支持通过拖放方式快速添加图片或文件夹</li><li><strong>顺序调整</strong>：可自由调整图片在PDF中的排列顺序</li><li><strong>尺寸控制</strong>：提供保留原始尺寸选项，确保图片清晰度</li><li><strong>子文件夹穿透</strong>：可自动搜索并添加子文件夹中的所有图片</li></ul><h3 id="程序说明" tabindex="-1">程序说明 <a class="header-anchor" href="#程序说明" aria-label="Permalink to &quot;程序说明&quot;">​</a></h3><ul><li><strong>输入路径区域</strong>：用于选择包含图片的文件夹路径，如果是输入的文件夹路径，需要键盘回车键确认来加载图片</li><li><strong>输出路径区域</strong>：用于选择转换后PDF文件的保存位置</li><li><strong>选项区域</strong>：包含四个复选框，分别是&quot;所有图片合并为一个PDF&quot;、&quot;每张图片生成单独PDF&quot;、&quot;保留原始尺寸&quot;、&quot;启用子文件夹穿透&quot;</li><li><strong>按钮区域</strong>：包含&quot;添加图片/文件夹&quot;、&quot;移除选中&quot;、&quot;清空列表&quot;、&quot;上移图片&quot;、&quot;下移图片&quot;等操作按钮</li><li><strong>转换按钮</strong>：醒目的&quot;转换为PDF&quot;按钮，用于开始转换操作</li><li><strong>图片列表</strong>：显示已添加的图片文件路径</li></ul><h3 id="基本操作指南" tabindex="-1">基本操作指南 <a class="header-anchor" href="#基本操作指南" aria-label="Permalink to &quot;基本操作指南&quot;">​</a></h3><p><strong>添加图片</strong></p><ol><li>点击&quot;添加图片/文件夹&quot;按钮</li><li>根据需要选择单个或多个图片文件，或选择包含图片的文件夹</li><li>若启用了&quot;子文件夹穿透&quot;，工具会自动搜索并添加子文件夹中的所有图片</li></ol><p><strong>拖放添加</strong></p><ol><li>打开文件资源管理器，找到需要转换的图片或文件夹</li><li>将图片或文件夹直接拖放到工具的图片列表区域</li><li>工具会自动添加所有支持的图片文件</li></ol><p><strong>调整图片顺序</strong></p><ol><li>在图片列表中选中需要调整顺序的图片</li><li>点击&quot;上移图片&quot;或&quot;下移图片&quot;按钮调整位置</li><li>也可以直接拖动列表中的图片来调整顺序</li></ol><p><strong>设置输出选项</strong></p><ol><li>选择&quot;所有图片合并为一个PDF&quot;或&quot;每张图片生成单独PDF&quot;</li><li>如需保留图片原始尺寸，请勾选&quot;保留原始尺寸&quot;</li><li>如需搜索子文件夹中的图片，请勾选&quot;启用子文件夹穿透&quot;</li></ol><p><strong>选择输出目录</strong></p><ol><li>点击&quot;选择输出目录&quot;按钮</li><li>在弹出的对话框中选择或创建一个文件夹作为输出目录</li><li>点击&quot;确定&quot;按钮</li></ol><p><strong>开始转换</strong></p><ol><li>确认所有设置已完成</li><li>点击&quot;转换为PDF&quot;按钮开始转换</li><li>等待进度条完成，转换完成后会弹出提示信息</li></ol><h3 id="实际使用场景示例" tabindex="-1">实际使用场景示例 <a class="header-anchor" href="#实际使用场景示例" aria-label="Permalink to &quot;实际使用场景示例&quot;">​</a></h3><p><strong>场景一：照片集合并</strong></p><p><strong>功能说明</strong>：将多张旅行照片合并为一个PDF文档，便于分享和保存。</p><p><strong>操作步骤</strong>：</p><ol><li>点击&quot;添加图片/文件夹&quot;按钮，选择存放旅行照片的文件夹</li><li>确保勾选了&quot;启用子文件夹穿透&quot;，以便添加所有子文件夹中的照片</li><li>勾选&quot;所有图片合并为一个PDF&quot;选项</li><li>点击&quot;选择输出目录&quot;，设置PDF文件的保存位置</li><li>点击&quot;转换为PDF&quot;按钮，等待转换完成</li><li>转换完成后，在输出目录的&quot;处理完成&quot;文件夹中找到合并后的PDF文件</li></ol><p><strong>场景二：文档扫描件处理</strong></p><p><strong>功能说明</strong>：将纸质文档扫描成多张图片后，转换为一个PDF文档以便归档。</p><p><strong>操作步骤</strong>：</p><ol><li>将扫描得到的图片文件添加到工具中</li><li>根据文档顺序，使用&quot;上移图片&quot;和&quot;下移图片&quot;按钮调整图片顺序</li><li>勾选&quot;所有图片合并为一个PDF&quot;选项</li><li>勾选&quot;保留原始尺寸&quot;选项，确保文档清晰度</li><li>设置输出目录并点击&quot;转换为PDF&quot;按钮</li><li>转换完成后，在输出目录中查看生成的PDF文档</li></ol><p><strong>场景三：多张图片分别转换</strong></p><p><strong>功能说明</strong>：将多张图片分别转换为单独的PDF文件，用于制作单页文档。</p><p><strong>操作步骤</strong>：</p><ol><li>添加需要转换的所有图片</li><li>勾选&quot;每张图片生成单独PDF&quot;选项</li><li>根据需要选择是否保留原始尺寸</li><li>设置输出目录并点击&quot;转换为PDF&quot;按钮</li><li>转换完成后，在输出目录的&quot;处理完成&quot;文件夹中可以找到所有生成的PDF文件</li></ol><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ol><li><strong>文件格式</strong>：本工具支持常见的图片格式（如JPG、PNG、BMP等），不支持非图片格式文件</li><li><strong>性能问题</strong>：转换大量图片或高分辨率图片时，可能会消耗较多系统资源，请确保电脑有足够的性能</li><li><strong>路径长度</strong>：Windows系统对文件路径长度有限制，请避免使用过深的文件夹层级</li><li><strong>文件命名</strong>：请确保图片文件名称不包含特殊字符，以免影响转换</li></ol><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p></blockquote><h3 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to &quot;常见问题解答&quot;">​</a></h3><p><strong>问题1：为什么有些图片无法添加到列表中？</strong></p><p><strong>解答</strong>：可能是因为这些图片格式不受支持，或者文件已损坏。请确保图片格式为常见的图片格式（如JPG、PNG、BMP等），并尝试打开图片确认文件是否完整。</p><p><strong>问题2：转换过程中程序无响应怎么办？</strong></p><p><strong>解答</strong>：这可能是因为正在处理大量图片或高分辨率图片，程序需要一定时间完成转换。请耐心等待，不要强制关闭程序。如果长时间无响应，可以尝试减少一次处理的图片数量。</p><p><strong>问题3：转换后的PDF文件在哪里？</strong></p><p><strong>解答</strong>：转换后的PDF文件保存在您指定的输出目录下的&quot;处理完成&quot;文件夹中。如果没有指定输出目录，则保存在输入目录下的&quot;处理完成&quot;文件夹中。</p><p><strong>问题4：如何调整PDF中图片的顺序？</strong></p><p><strong>解答</strong>：在图片列表中，您可以通过点击&quot;上移图片&quot;和&quot;下移图片&quot;按钮来调整图片顺序，也可以直接拖动列表中的图片来调整顺序。PDF中图片的顺序与列表中显示的顺序一致。</p><p><strong>问题5：为什么转换后的PDF文件比原始图片小很多？</strong></p><p><strong>解答</strong>：这是因为PDF格式会对图片进行一定的压缩。如果您希望保留更多细节，可以勾选&quot;保留原始尺寸&quot;选项。</p><h3 id="📑-程序使用说明" tabindex="-1">📑 程序使用说明 <a class="header-anchor" href="#📑-程序使用说明" aria-label="Permalink to &quot;📑 程序使用说明&quot;">​</a></h3><p><strong>双击使用即可，可执行文件（.exe文件），双击该文件即可启动工具。</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251021141103176102706351038.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2035.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2035.html</a></p>',53)])])}const h=o(r,[["render",s]]);export{d as __pageData,h as default};
